INSERT INTO lessons(language_id, cefr_code, slug, title, description, situation, tip, sort_order, status, published_at, updated_at, revision) VALUES ((SELECT id FROM languages WHERE code = 'te'), 'A1', 'greetings', 'Greetings', 'Greet people politely and introduce yourself in Telugu.', 'You''ve just rented a flat in Madhapur. Lakshmi garu, the house owner, comes to say hello.', '“Namaskaram” is the respectful hello. Add “garu” after a name to be respectful (“Lakshmi garu”), and “andi” to soften a reply (“avunandi”, yes). The polite “you” is “meeru”, and polite requests end in -andi: “cheppandi” (please say), “ivvandi” (please give).', 1, 'published', datetime('now'), datetime('now'), 1);
