INSERT INTO lessons(language_id, cefr_code, slug, title, description, situation, tip, sort_order, status, published_at, updated_at, revision) VALUES ((SELECT id FROM languages WHERE code = 'te'), 'A1', 'transport', 'Transport', 'Take autos and the Hyderabad Metro.', 'You''ve arrived at Secunderabad station and need to get to Banjara Hills.', 'Hyderabad autos should go by the meter, but many drivers quote a fare instead: ask for the meter, agree the fare first, or book an app ride. The metro has three lines: Red (Miyapur–LB Nagar), Blue (Nagole–Raidurg) and Green (JBS Parade Ground–MGBS).', 2, 'published', datetime('now'), datetime('now'), 1);
