INSERT INTO grammar_topic_texts(grammar_topic_id, language_id, title, explanation) VALUES ((SELECT id FROM grammar_topics WHERE language_id = (SELECT id FROM languages WHERE code = 'te') AND slug = 'polite-requests'), (SELECT id FROM languages WHERE code = 'en'), 'Polite requests: “ivvandi”, “cheyandi”, “cheppandi”', 'Telugu asks politely with the “meeru” (you, polite) form, which ends in -andi: “ivvandi” (please give), “cheyandi” (please do), “cheppandi” (please say), “aapandi” (please stop). With friends the short form is used: “ivvu”, “cheyyi”, “cheppu”.');
